mapper.select:
SELECT a.pet_id, a.pet_name, a.pet_variety, a.pet_sex, a.pet_birthday,
       a.client_id, b.client_name, b.client_tel
FROM pet AS a
LEFT JOIN client AS b ON a.client_id = b.client_id
WHERE a.is_del = 0 AND a.pet_alive = 1 AND a.client_id IS NOT NULL


    AND (a.pet_name LIKE #{kwLike}
      OR a.pet_variety LIKE #{kwLike}
      OR a.pet_chip LIKE #{kwLike}
      OR b.client_name LIKE #{kwLike}
      OR b.client_tel LIKE #{kwLike}
      OR CAST(a.pet_id AS CHAR) = #{kw})

ORDER BY a.pet_id DESC
LIMIT 20
